// Types for the Luxembourg dataset generated by prototipo/build/build_data.py.
// The JSON itself is exported as "@wtl/data-lux/<name>.json" (see package.json "exports"). Those subpaths need
// package-exports resolution (Metro: resolver.unstable_enablePackageExports, on by default since RN 0.79 / Expo 53);
// "main" only covers the root import.
// transit.json is ~1.3 MB: an app may load it as an asset (expo-asset + fetch) instead of bundling the import,
// to keep JS bundle parse time down. @wtl/core copies `conns` into a typed array once in createTransit().

/** POI categories that have a distance layer in the grid (doctor is built but not used in v0). */
export type DistKey =
  | 'supermarket'
  | 'pharmacy'
  | 'hospital'
  | 'doctor'
  | 'school'
  | 'nursery'
  | 'afterschool'
  | 'university'
  | 'park'
  | 'gym'
  | 'nightlife'
  | 'bikeshare';

/** 150 m grid, row-major (row 0 = south). All per-cell arrays have length rows × cols. */
export interface Grid {
  lat0: number;
  lon0: number;
  dlat: number;
  dlon: number;
  rows: number;
  cols: number;
  built: string;
  /** Index into AREAS, or -1 outside the covered communes. */
  area: number[];
  /** Lden band in dB (0 = below 55 or not mapped; 55, 60, 65, 70, 75). */
  noise_road: number[];
  noise_rail: number[];
  noise_air: number[];
  /** Aircraft Lnight band in dB (0, 45, 50, …). */
  noise_air_night?: number[];
  /** Noise map coverage: 2 = inside the agglomeration map (all sources), 1 = major axes only. */
  noise_cov: number[];
  /** Ground elevation in metres. */
  elev?: number[];
  /** Distance to nearest POI per category, in units of 10 m (capped). */
  dist: Record<DistKey, number[]>;
}

export interface Area {
  name: string;
  kind: string;
  /** Published average asking rent €/m² (null when not published). */
  eur_m2: number | null;
  offers: number | null;
  avg_rent: number | null;
  estimated: boolean;
  /** Price level used by the size model. */
  L: number | null;
  L_default: boolean;
}

/** [lat, lon, category, name] */
export type Poi = [number, number, string, string | null];

export interface Transit {
  /** Modelled weekday (YYYY-MM-DD). */
  day: string;
  /** Number of values per connection in `conns` (6 = dep, arr, from, to, trip, flags). */
  stride?: number;
  /** [lat, lon] per stop. */
  stops: [number, number][];
  /**
   * Flat connection list sorted by departure in DESCENDING order (latest first, as build_data.py writes it),
   * `stride` values each; times in seconds since midnight. The reverse connection scan depends on this order;
   * @wtl/core createTransit() checks it and throws otherwise.
   */
  conns: number[];
}

export interface Meta {
  generated_from: string;
  files: Record<string, { source: string; source_bytes: number; json_bytes: number }>;
  built?: string | null;
  region?: number[] | null;
  step_km?: number | null;
  sources?: Record<
    string,
    { url: string; last_modified: string | null; downloaded: string | null }
  >;
  transit_day?: string | null;
}

export interface LuxData {
  grid: Grid;
  areas: Area[];
  pois?: Poi[];
  transit: Transit;
}
